"""Rebuild static Atlas pages from local content and image credit manifests."""
import json,re,html
from pathlib import Path
BASE=Path(__file__).resolve().parents[1];ROOT=BASE/'site'
STORIES=json.loads((BASE/'content.json').read_text());BY={s['slug']:s for s in STORIES}
CREDITS=json.loads((ROOT/'assets/photos/credits.json').read_text());C={c['slug']:c for c in CREDITS}
esc=lambda s:html.escape(str(s),quote=True)
icon='<svg viewBox="0 0 40 40" fill="none" aria-hidden="true"><circle cx="20" cy="20" r="18" stroke="currentColor"/><ellipse cx="20" cy="20" rx="9" ry="18" stroke="currentColor"/><path d="M2 20h36M5 10h30M5 30h30" stroke="currentColor"/></svg>'
search='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/></svg>'
nav=[('Explore','explore.html'),('Geography','geography.html'),('Cartography','cartography.html'),('Earth Science','earth-science.html'),('About','about.html')]
def brand(pre=''):return f'<a class="brand" href="{pre}index.html" aria-label="Atlas home"><span class="brand-symbol">{icon}</span><span class="brand-name">ATLAS<small>EARTH &amp; PLACE</small></span></a>'
def picture(slug,pre='',lazy=True):
 c=C[slug];return f'<img src="{pre}{c["file"]}" alt="{esc(c["title"])}" width="1400" height="900" {"loading=lazy" if lazy else "fetchpriority=high"} decoding="async">'
def card(slug,pre='',kind=''):
 s=BY[slug];return f'''<a class="story {kind}" href="{pre}articles/{slug}.html" data-story data-category="{esc(s['category'])}" data-search="{esc(s['title']+' '+s['dek'])}"><div class="story-image">{picture(slug,pre)}</div><div class="story-content"><div class="story-meta"><span>{esc(s['category'])}</span><span>{s['minutes']} min read</span></div><h3>{esc(s['title'])}</h3><p>{esc(s['dek'])}</p></div></a>'''
def page(name,title,description,body,active='',article=False):
 pre='../' if article else ''
 links=''.join(f'<a href="{pre}{url}" '+('aria-current="page"' if text==active else '')+f'>{text}</a>' for text,url in nav)
 footer=f'''<footer class="footer"><div class="wrap"><div class="footer-grid"><div>{brand(pre)}<p>A closer look at the landscapes, maps and forces that make our planet. An independent educational atlas, open to every curious mind.</p></div><div><h3>Explore the planet</h3><a href="{pre}geography.html">Land &amp; water</a><a href="{pre}cartography.html">Maps &amp; perspectives</a><a href="{pre}earth-science.html">Earth in motion</a></div><div><h3>Inside Atlas</h3><a href="{pre}about.html">Our approach</a><a href="{pre}sources.html">Sources &amp; image credits</a><a href="{pre}explore.html?saved=1">Your reading list</a></div></div><div class="footer-bottom"><span>© 2026 Atlas — Earth &amp; Place</span><span>Independent. Curious. Open.</span></div></div></footer>'''
 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} — Atlas</title><meta name="description" content="{esc(description)}"><meta name="theme-color" content="#142d35"><meta property="og:title" content="{esc(title)} — Atlas"><meta property="og:description" content="{esc(description)}"><meta property="og:type" content="{'article' if article else 'website'}"><link rel="icon" href="{pre}assets/img/favicon.svg"><link rel="stylesheet" href="{pre}assets/css/styles.css"><script src="{pre}assets/js/app.js" defer></script>{'<script src="assets/js/globe.js" defer></script>' if name=='index.html' else ''}</head><body><a class="skip" href="#main">Skip to content</a>{'<div class="reading-progress" data-reading-progress></div>' if article else ''}<header class="header"><div class="wrap">{brand(pre)}<nav class="nav" id="main-navigation" aria-label="Main navigation">{links}</nav><div class="header-actions"><button class="icon-button" data-search-toggle aria-label="Search Atlas" aria-expanded="false" aria-controls="site-search">{search}</button><button class="icon-button menu-button" data-menu-toggle aria-label="Open navigation" aria-expanded="false" aria-controls="main-navigation"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M4 7h16M4 12h16M4 17h16"/></svg></button></div></div><div class="search-panel" id="site-search" hidden><form class="wrap" action="{pre}explore.html"><input type="search" name="q" aria-label="Search stories" placeholder="Landscapes, oceans, maps…"><button class="button" type="submit">Search</button></form></div></header><main id="main">{body}</main>{footer}</body></html>'''
 (ROOT/name).write_text(out)
hero='''<section class="hero"><div class="wrap"><div class="hero-topline"><span>A journal for the geographically curious</span><span>Land · water · the space between</span></div><div class="hero-grid"><div class="hero-copy reveal"><div class="eyebrow">A different perspective</div><h1>The world is<br>worth a <em>closer look.</em></h1><p>Beyond the lines on a map lies a living planet. Follow its contours, cross its oceans, and discover the stories written into the land.</p><div class="actions"><a class="button" href="explore.html">Explore the atlas</a><a class="text-link" href="about.html">Our approach</a></div><div class="hero-foot">Eight stories. Countless ways of seeing.</div></div><div class="globe-scene"><img class="globe-fallback" src="assets/photos/earth-from-space.webp" alt="Earth seen from space" data-globe-fallback><canvas id="earth-globe" tabindex="0" role="img" aria-label="Interactive Earth. Drag horizontally or vertically to rotate; arrow keys rotate, plus and minus zoom, space pauses."></canvas><div class="globe-label">The living atlas<span>Earth / satellite mosaic</span></div><div class="globe-credit">Drag to explore · scroll to zoom<br>Imagery: NASA / Blue Marble</div><div class="globe-controls"><button data-globe-left aria-label="Rotate Earth left">‹</button><button data-globe-right aria-label="Rotate Earth right">›</button><button data-globe-zoom-in aria-label="Zoom in">+</button><button data-globe-zoom-out aria-label="Zoom out">−</button><button data-globe-pause class="pause" aria-label="Pause globe rotation">Pause</button><span class="globe-coordinates" data-globe-coordinates>GLOBAL VIEW</span></div></div></div></div></section><div class="facts"><div class="wrap"><div class="fact"><strong>71%</strong><span>of Earth's surface is covered by water</span></div><div class="fact"><strong>5</strong><span>Great Lakes. One connected freshwater system.</span></div><div class="fact"><strong>3</strong><span>perspectives: geography, cartography &amp; Earth science</span></div></div></div>'''
body=hero+f'''<section class="section wrap"><div class="section-head"><div><div class="eyebrow">Editor's selection</div><h2>Stories shaped by place.</h2></div><a class="text-link" href="explore.html">All stories</a></div><div class="feature-grid">{card('great-lakes',kind='large')}<div class="story-stack">{card('mountain-building')}{card('topographic-maps',kind='compact')}</div></div></section><section class="landscape-feature">{picture('tectonic-plates')}<div class="wrap"><div class="eyebrow">Earth in motion</div><h2>Nothing beneath<br>our feet stands still.</h2><p>Continents drift. Ocean floors open. Mountains rise. Read the slow, extraordinary story of a restless planet.</p><a class="text-link" href="articles/tectonic-plates.html">Discover plate tectonics</a></div></section><section class="section wrap"><div class="section-head"><div><div class="eyebrow">Choose your lens</div><h2>One planet. Many perspectives.</h2></div><p>Start with a landscape. Follow a question. See where it takes you.</p></div><div class="topics">'''
for label,url,slug,desc in [('Geography','geography.html','ocean-currents','Landscapes, coastlines and connected waters.'),('Cartography','cartography.html','evolution-of-maps','The art and science of finding our place.'),('Earth Science','earth-science.html','mountain-building','A planet that never stops changing.')]:body+=f'<a class="topic" href="{url}">{picture(slug)}<h3>{label}</h3><p>{desc}</p></a>'
body+=f'''</div></section><section class="wrap field-note"><div><div class="eyebrow">A note from Atlas</div><h2 class="split-title">Look past<br>the familiar.</h2></div><div><p>A coastline is more than an edge. A mountain is more than a summit. Every place has a longer story — of water, rock, time, and the ways we learn to see.</p><p class="small">Thoughtful introductions, clear explanations, and sources you can follow.</p><a class="text-link" href="about.html">Meet the project</a></div></section><section class="section wrap"><div class="section-head"><div><div class="eyebrow">Further afield</div><h2>Keep your curiosity moving.</h2></div></div><div class="related-grid">{card('ocean-currents')}{card('rivers-and-deltas')}{card('earth-from-space')}</div></section>'''
page('index.html','A closer look at our planet','An independent atlas of geography, maps and Earth science. Explore real landscapes and an interactive satellite globe.',body)
intros={
 'Explore':('Follow your curiosity.','Browse the complete Atlas collection. Find a new perspective on water, land, maps, and the forces beneath our feet.'),
 'Geography':('The shape of place.','From freshwater shores to branching deltas: explore the landscapes that connect water, climate, and life.'),
 'Cartography':('A world of perspectives.','Every map makes a choice. Learn to read the land, and discover how our picture of the world has changed.'),
 'Earth Science':('A planet in motion.','Understand the deep forces shaping Earth, and the remarkable tools that let us see them.')}
for category,file in [('Explore','explore.html'),('Geography','geography.html'),('Cartography','cartography.html'),('Earth Science','earth-science.html')]:
 title,dek=intros[category]
 listing=STORIES if category=='Explore' else [s for s in STORIES if s['category']==category]
 tools=''
 if category=='Explore':tools='<div class="filters" aria-label="Filter by topic">'+''.join(f'<button class="filter" data-filter="{c}" aria-pressed="{str(c=="All").lower()}">{c}</button>' for c in ['All','Geography','Cartography','Earth Science','Saved'])+'</div>'
 body=f'<section class="page-hero"><div class="wrap"><div class="eyebrow">{category}</div><h1>{title}</h1><p class="dek">{dek}</p></div></section><section class="section wrap" data-catalog><div class="catalog-tools">{tools}<input class="catalog-search" type="search" data-story-search aria-label="Search this collection" placeholder="Search this collection…"></div><div class="count" data-count aria-live="polite">{len(listing)} stories</div><div class="catalog">'+''.join(card(s['slug']) for s in listing)+'</div><p class="empty" data-empty hidden>No stories match your selection. Try another topic or search.</p></section>'
 page(file,category,dek,body,category)
for s in STORIES:
 slug=s['slug'];c=C[slug];bodytext=s['body'];headings=re.findall('<h2 id="([^"]+)">(.*?)</h2>',bodytext)
 toc=''.join(f'<a href="#{id}">{text}</a>' for id,text in headings)
 related=[t for t in STORIES if t['slug']!=slug];related=sorted(related,key=lambda t:t['category']!=s['category'])[:3]
 body=f'''<article><header class="article-header wrap"><div class="breadcrumb"><a href="../index.html">Atlas</a> / <a href="../{dict((x,y) for x,y in nav)[s['category']]}">{s['category']}</a></div><div class="eyebrow">{s['category']}</div><h1>{esc(s['title'])}</h1><p class="dek">{esc(s['dek'])}</p><div class="article-meta"><span>Atlas explainers</span><span>{s['minutes']} minute read</span><span>Earth &amp; Place collection</span></div></header><figure class="article-cover wrap">{picture(slug,'../',False)}<figcaption>{esc(c['title'])} · {esc(c['author'])} · <a href="../sources.html#{slug}">{esc(c['license'])} / image credits</a></figcaption></figure><div class="article-layout wrap"><aside class="toc" aria-label="On this page"><h2>In this story</h2>{toc}<a href="#sources">Sources &amp; further reading</a></aside><div><div class="article-body">{bodytext}</div><div class="article-actions"><button data-save="{slug}" class="saved-button" aria-pressed="false">Save to reading list</button><button data-copy-link>Copy article link</button><span class="toast" data-toast role="status"></span></div></div></div></article><section class="related"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Keep exploring</div><h2>There is more to the story.</h2></div></div><div class="related-grid">{''.join(card(t['slug'],'../') for t in related)}</div></div></section>'''
 page('articles/'+slug+'.html',s['title'],s['dek'],body,s['category'],True)
about='''<section class="page-hero"><div class="wrap"><div class="eyebrow">About Atlas</div><h1>Curiosity is a way<br>of seeing.</h1><p class="dek">An independent educational guide to the planet — for anyone who has ever stopped to wonder why a landscape looks the way it does.</p></div></section><section class="wrap prose"><h2>A closer look, not a louder voice.</h2><p>Atlas brings together geography, cartography, and Earth science. We begin with familiar places and follow the less familiar processes behind them: the movement of ice, the work of rivers, the slow rise of mountains.</p><p>Our stories are introductions, not substitutes for specialist research. Each includes references so you can check the explanation and keep exploring.</p><h2>Images with a place and a provenance.</h2><p>Landscape photographs and historical maps are credited to their creators. Captions describe what is pictured; a photograph accompanying an explainer is not a claim of original field reporting. Our interactive globe uses a NASA satellite mosaic, not live imagery.</p><h2>Built for a quieter web.</h2><p>No accounts, adverts, tracking pixels, or subscription forms. Your reading list stays in your browser. Nothing is sent to a server when you save a story.</p><p><a href="sources.html">Read our sources and image credits</a> or <a href="explore.html">explore the collection</a>.</p></section>'''
page('about.html','About Atlas','A quieter, thoughtful guide to geography, maps, and the living planet.',about,'About')
credits='<section class="page-hero"><div class="wrap"><div class="eyebrow">Research &amp; provenance</div><h1>Follow the sources.</h1><p class="dek">Good explanations leave a trail. Here are the references, image creators, and reuse licences behind Atlas.</p></div></section><section class="wrap prose"><h2>Editorial references</h2><p>Each article links to educational and scientific organisations, including NASA, NOAA, USGS, EPA and the National Park Service. Read those sources for the underlying research and additional detail.</p><p>The globe is a visual exploration tool. Its satellite composite is not live, and its illumination is artistic rather than a real-time day/night model.</p><h2>Photography &amp; maps</h2><div class="credit-list">'
for c in CREDITS:credits+=f'<article id="{c["slug"]}"><h3>{esc(c["title"])}</h3><p>Creator: {esc(c["author"])}<br>Licence: <a href="{esc(c["license_url"])}">{esc(c["license"])}</a><br><a href="{esc(c["source"])}">Original file and full attribution</a><br>{esc(c["modified"])}</p></article>'
credits+='</div><h2>Satellite globe</h2><p>NASA Blue Marble imagery, distributed with the Three.js examples texture collection. Satellite composite credited to NASA / Reto Stöckli; freely available for public educational use. No endorsement implied. <a href="https://science.nasa.gov/earth/earth-observatory/the-blue-marble-true-color-global-imagery-at-1km-resolution/">NASA image background</a>; <a href="https://github.com/mrdoob/three.js/blob/dev/examples/textures/planets/earth_atmos_2048.jpg">texture source</a>.</p><h2>Surface water</h2><p>The homepage water coverage figure is rounded. <a href="https://www.usgs.gov/media/images/distribution-water-and-above-earth">USGS: distribution of water on Earth</a>.</p></section>'
page('sources.html','Sources & image credits','Research references, photographer attribution, and image licences for Atlas.',credits)
page('404.html','A little off the map','Find your way back to the Atlas collection.','<section class="page-hero"><div class="wrap"><div class="eyebrow">Page not found</div><h1>A little off the map.</h1><p class="dek">This page is not in our atlas. There is still plenty to discover.</p><a class="button" href="index.html">Return to Atlas</a></div></section>')
print('Rendered',len(list(ROOT.rglob('*.html'))),'static pages')
